(33, 'LR2610010001', NULL, 'def simulan_ang_quiz():\n    print(\"========================================\")\n    print(\"       MALIGAYAG PAGDATING SA QUIZ!     \")\n    print(\"========================================\")\n    \n    # Listahan ng mga tanong, pagpipilian, at tamang sagot (index ng pagpipilian)\n    mga_tanong = [\n        {\n            \"tanong\": \"1. Ano ang pangunahing ginagamit na programming language sa Machine Learning at AI?\",\n            \"pagpipilian\": [\"A. HTML\", \"B. Python\", \"C. CSS\", \"D. SQL\"],\n            \"sagot\": \"B\"\n        },\n        {\n            \"tanong\": \"2. Alin sa mga sumusunod ang database management system?\",\n            \"pagpipilian\": [\"A. MySQL\", \"B. Python\", \"C. Flask\", \"D. Git\"],\n            \"sagot\": \"A\"\n        },\n        {\n            \"tanong\": \"3. Ano ang tawag sa balangkas o framework na kadalasang ginagamit sa Python para sa web development?\",\n            \"pagpipilian\": [\"A. React\", \"B. Laravel\", \"C. Flask\", \"D. Flutter\"],\n            \"sagot\": \"C\"\n        }\n    ]\n    \n    puntos = 0\n    kabuuan = len(mga_tanong)\n    \n    # Pag-ikot sa bawat tanong\n    for index, item in enumerate(mga_tanong, start=1):\n        print(f\"\\n{item[\'tanong\']}\")\n        for pagpipilian in item[\"pagpipilian\"]:\n            print(pagpipilian)\n            \n        sagot_ng_user = input(\"Ilagay ang iyong sagot (A/B/C/D): \").strip().upper()\n        \n        if sagot_ng_user == item[\"sagot\"]:\n            print(\"Tama! Magaling.\")\n            puntos += 1\n        else:\n            print(f\"Mali! Ang tamang sagot ay {item[\'sagot\']}.\")\n            \n    # Resulta\n    print(\"\\n========================================\")\n    print(\"               TAPOS NA ANG QUIZ!       \")\n    print(\"========================================\")\n    print(f\"Ang iyong kabuuang puntos ay: {puntos} sa {kabuuan}\")\n    \n    porsiyento = (puntos / kabuuan) * 100\n    if porsiyento == 100:\n        print(\"Perpekto! Napakahusay mo!\")\n    elif porsiyento >= 50:\n        print(\"Magaling! Nakapasa ka.\")\n    else:\n        print(\"Kailangan mo pang mag-aral nang konti. Subukan ulit!\")\n\nif __name__ == \"__main__\":\n    simulan_ang_quiz()', 'Traceback (most recent call last):\n  File \"<exec>\", line 39, in <module>\n  File \"<exec>\", line 36, in _cobrabyte_exec_async\n  File \"<sandbox>\", line 34\nSyntaxError: \'await\' outside async function', 'error', 34.400, '2026-10-01 00:39:51'),
(34, 'LR2610010001', NULL, 'salita = input(\"Maglagay ng salita: \")\nprint(f\"Baligtad: {salita[::-1]}\")', 'Maglagay ng salita: HAHAHAAHAHAHAHAHAHAHAHAHAM\nBaligtad: MAHAHAHAHAHAHAHAHAHAAHAHAH', 'success', 32.500, '2026-10-01 00:41:54'),
(35, 'LR2610010001', NULL, 'def ipakita_ang_menu():\n    print(\"\\n==============================\")\n    print(\"   CONTACT MANAGEMENT SYSTEM  \")\n    print(\"==============================\")\n    print(\"[1] Tingnan lahat ng contacts\")\n    print(\"[2] Magdagdag ng contact\")\n    print(\"[3] Maghanap ng contact\")\n    print(\"[4] Mag-delete ng contact\")\n    print(\"[5] Lumabas\")\n\ndef contact_system():\n    # Paunang mga contact bilang halimbawa\n    contacts = {\n        \"Juan\": \"09123456789\",\n        \"Maria\": \"09987654321\"\n    }\n    \n    while True:\n        ipakita_ang_menu()\n        pili = input(\"\\nPumili ng opsyon (1-5): \").strip()\n        \n        if pili == \'1\':\n            print(\"\\n--- Listahan ng Contacts ---\")\n            if not contacts:\n                print(\"Walang nakaimbak na contact.\")\n            else:\n                for pangalan, numero in contacts.items():\n                    print(f\"Pangalan: {pangalan} | Numero: {numero}\")\n                    \n        elif pili == \'2\':\n            print(\"\\n--- Magdagdag ng Contact ---\")\n            pangalan = input(\"Ilagay ang pangalan: \").strip()\n            if not pangalan:\n                print(\"Bawal ang blangkong pangalan!\")\n                continue\n            numero = input(\"Ilagay ang numero: \").strip()\n            contacts[pangalan] = numero\n            print(f\"Matagumpay na naidagdag si {pangalan}!\")\n            \n        elif pili == \'3\':\n            print(\"\\n--- Maghanap ng Contact ---\")\n            hahanapin = input(\"Ilagay ang pangalan na hahanapin: \").strip()\n            if hahanapin in contacts:\n                print(f\"Nakita! {hahanapin}: {contacts[hahanapin]}\")\n            else:\n                print(f\"Walang contact na may pangalang \'{hahanapin}\'.\")\n                \n        elif pili == \'4\':\n            print(\"\\n--- Mag-delete ng Contact ---\")\n            tatanggalin = input(\"Ilagay ang pangalan na tatanggalin: \").strip()\n            if tatanggalin in contacts:\n                del contacts[tatanggalin]\n                print(f\"Matagumpay na na-delete si {tatanggalin}!\")\n            else:\n                print(f\"Hindi nahanap ang pangalang \'{tatanggalin}\'.\")\n                \n        elif pili == \'5\':\n            print(\"\\nMaraming salamat sa paggamit ng Contact System. Paalam!\")\n            break\n        else:\n            print(\"Maling opsyon. Mangyaring pumili lamang mula 1 hanggang 5.\")\n\nif __name__ == \"__main__\":\n    contact_system()', 'Traceback (most recent call last):\n  File \"<exec>\", line 39, in <module>\n  File \"<exec>\", line 36, in _cobrabyte_exec_async\n  File \"<sandbox>\", line 20\nSyntaxError: \'await\' outside async function', 'error', 33.900, '2026-10-01 00:42:30'),
